// isRefreshTargeted reports whether `res` should be refreshed during a program-based refresh
// (RefreshV2), honoring any `--target` or `--exclude` filters. When targets are constrained only
// the targeted resources are refreshed; when excludes are constrained everything except the
// excluded resources is refreshed. Without either constraint every resource is refreshed.
func (sg *stepGenerator) isRefreshTargeted(res *resource.State) bool {
	if sg.deployment.opts.Targets.IsConstrained() {
		return sg.isTargetedForUpdate(res)
	} else if sg.deployment.opts.Excludes.IsConstrained() {
		return !sg.isExcludedFromUpdate(res)
	}
	return true
}

